'use strict';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA');
const initial=()=>({version:1,profile:{name:'我的',exam:'2028-05-01'},subjects:[],tasks:[],logs:[],grades:[],core:[]});
let data;try{data=JSON.parse(localStorage.getItem('ib-atlas-v1'))||initial()}catch{data=initial()}
let page='dashboard',filter='',status='all';
const nav=[['dashboard','◫','学习总览'],['subjects','▦','我的学科'],['tasks','☑','任务与计划'],['logs','▤','学习日志'],['grades','↗','成绩追踪'],['core','◇','核心项目'],['focus','◷','专注时光'],['settings','⚙','个人设置']];
const groups=[['语言与文学','Chinese A: Literature','Chinese A: Language and Literature','English A: Literature','English A: Language and Literature','Language A: Literature（自选语言）','Language A: Language and Literature（自选语言）','Literature and Performance'],['语言习得','English B','Chinese B','French B','Spanish B','French ab initio','Spanish ab initio','Language B（自选语言）','Language ab initio（自选语言）','Latin','Classical Greek'],['个体与社会','Economics','Business Management','History','Geography','Psychology','Global Politics','Digital Society','Philosophy','Social and Cultural Anthropology','World Religions'],['科学','Biology','Chemistry','Physics','Computer Science','Design Technology','Sports, Exercise and Health Science','Environmental Systems and Societies'],['数学','Mathematics: Analysis and Approaches','Mathematics: Applications and Interpretation'],['艺术','Visual Arts','Music','Theatre','Film','Dance']];
const save=()=>{try{localStorage.setItem('ib-atlas-v1',JSON.stringify(data));return true}catch{toast('保存失败：浏览器存储空间不足，请导出备份');return false}};
const toast=t=>{$('#toast').textContent=t;$('#toast').style.display='block';clearTimeout(window.toastTimeout);window.toastTimeout=setTimeout(()=>$('#toast').style.display='none',3000)};
const subjectName=id=>data.subjects.find(s=>s.id===id)?.name||'综合 / 核心';
const options=()=>'<option value="">综合 / 核心</option>'+data.subjects.map(s=>`<option value="${s.id}">${esc(s.name)} · ${s.level}</option>`).join('');
const field=(label,name,type='text',value='',extra='')=>`<label for="f-${name}">${label}</label><input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`;
const select=(label,name,opts)=>`<label for="f-${name}">${label}</label><select id="f-${name}" name="${name}">${opts}</select>`;
const area=(label,name,value='')=>`<label for="f-${name}">${label}</label><textarea id="f-${name}" name="${name}">${esc(value)}</textarea>`;
function modal(title,html,handler){$('#modal-title').textContent=title;$('#fields').innerHTML=html;$('#form').onsubmit=e=>{e.preventDefault();try{handler(Object.fromEntries(new FormData(e.target)));if(save()){$('#modal').close();render();toast('已保存')}}catch(err){toast(err.message)}};$('#modal').showModal()}
$('#close').onclick=$('#cancel').onclick=()=>$('#modal').close();
function add(kind,id){let old=id?data[kind]?.find(x=>x.id===id):null;const insert=obj=>{obj.id=id||crypto.randomUUID();if(old)Object.assign(old,obj);else data[kind].push(obj)};
if(kind==='subjects'){modal(old?'编辑学科':'添加我的学科',select('学科组','group',groups.map((g,i)=>`<option value="${i}">${i+1} · ${g[0]}</option>`).join(''))+field('科目名称（可选择或自行填写）','name','text',old?.name||'','required list="catalog" maxlength="100"')+'<datalist id="catalog">'+groups.flatMap(g=>g.slice(1)).map(n=>`<option value="${esc(n)}">`).join('')+'</datalist>'+select('课程级别','level','<option>HL</option><option>SL</option>')+field('目标分数','target','number',old?.target||7,'required min="1" max="7"')+field('学习进度 %','progress','number',old?.progress||0,'required min="0" max="100"')+area('知识点、复习重点与个人笔记','notes',old?.notes||''),v=>{if(!old&&data.subjects.length>=8)throw Error('最多支持 8 门科目');insert({...v,target:+v.target,progress:+v.progress})});if(old){$('#f-group').value=old.group;$('#f-level').value=old.level}return}
if(kind==='tasks')modal(old?'编辑任务':'添加学习任务',field('任务名称','title','text',old?.title||'','required maxlength="180"')+select('关联科目','subject',options())+'<div class="split"><div>'+field('截止日期','date','date',old?.date||today(),'required')+'</div><div>'+select('优先级','priority','<option>普通</option><option>重要</option><option>紧急</option>')+'</div></div>'+select('任务类别','type',['作业','复习','考试','IA','EE','TOK','CAS'].map(s=>`<option>${s}</option>`).join(''))+area('任务说明','notes',old?.notes||''),v=>insert({...v,done:old?.done||false}));
if(kind==='logs')modal(old?'编辑日志':'记录今天的学习',field('学习主题','title','text',old?.title||'','required maxlength="180"')+select('关联科目','subject',options())+'<div class="split"><div>'+field('日期','date','date',old?.date||today(),'required')+'</div><div>'+field('学习时长（分钟）','minutes','number',old?.minutes||30,'required min="1" max="1440"')+'</div></div>'+area('学到了什么？有哪些疑问？下一步是什么？','notes',old?.notes||''),v=>insert({...v,minutes:+v.minutes}));
if(kind==='grades')modal(old?'编辑成绩':'记录一次成绩',field('测评名称','title','text',old?.title||'','required maxlength="180"')+select('科目','subject',options())+field('日期','date','date',old?.date||today(),'required')+'<div class="split"><div>'+field('IB 等级（1–7）','score','number',old?.score||'','required min="1" max="7"')+'</div><div>'+field('原始分数（可选，如 78/100）','raw','text',old?.raw||'')+'</div></div>'+area('老师反馈与改进方向','notes',old?.notes||''),v=>insert({...v,score:+v.score}));
if(kind==='core')modal(old?'编辑项目记录':'添加核心项目记录',select('核心项目','type',['IA','EE','TOK','CAS'].map(t=>`<option>${t}</option>`).join(''))+field('项目 / 阶段名称','title','text',old?.title||'','required maxlength="180"')+select('关联科目','subject',options())+field('计划完成日期','date','date',old?.date||today(),'required')+select('进度','stage',['未开始','进行中','待反馈','已完成'].map(t=>`<option>${t}</option>`).join(''))+area('研究问题、行动、反思或证据链接','notes',old?.notes||''),v=>insert(v));
if(old){for(const k of ['subject','priority','type','stage'])if($('#f-'+k))$('#f-'+k).value=old[k]||''}}
function head(title,subtitle,button='',kind=''){return `<div class="heading"><div><div class="eyebrow">YOUR DIPLOMA, YOUR JOURNEY</div><h1>${title}</h1><p class="sub">${subtitle}</p></div>${button?`<button class="primary" data-add="${kind}">＋ ${button}</button>`:''}</div>`}
function empty(title,desc){return `<div class="empty"><b>${title}</b>${desc}</div>`}
function taskRows(items){return items.length?items.map(t=>`<div class="row"><input class="check" type="checkbox" aria-label="完成 ${esc(t.title)}" data-check="${t.id}" ${t.done?'checked':''}><div class="row-body"><a href="#" data-edit="tasks:${t.id}" class="row-title ${t.done?'done':''}">${esc(t.title)}</a><small>${esc(subjectName(t.subject))} · ${esc(t.date)} ${!t.done&&t.date<today()?'· 已逾期':''}</small></div><span class="tag ${t.priority==='紧急'?'orange':''}">${esc(t.type)}</span><button class="delete" data-delete="tasks:${t.id}" aria-label="删除任务">×</button></div>`).join(''):empty('给下一步，留一个位置','添加作业、复习计划或即将到来的考试。')}
function subjectCards(){return data.subjects.map((s,i)=>`<article class="subject" tabindex="0" role="button" data-edit="subjects:${s.id}"><div class="subject-icon">${['Aa','文','◎','⚗','∑','✳'][s.group]||'◇'}</div><span class="tag ${s.level==='HL'?'blue':''}" style="float:right">${s.level}</span><h3>${esc(s.name)}</h3><p>GROUP ${+s.group+1} · ${groups[s.group]?.[0]||'自选课程'}</p><div class="progress"><i style="width:${s.progress}%"></i></div><div class="subject-foot"><span>学习进度 ${s.progress}%</span><span>目标 ${s.target} / 7</span></div></article>`).join('')}
function render(){page=location.hash.slice(1)||'dashboard';if(!nav.some(n=>n[0]===page))page='dashboard';$('#nav').innerHTML=nav.map(([id,icon,name])=>`<a href="#${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span>${icon}</span>${name}</a>`).join('');$('#breadcrumb').textContent='我的空间 / '+nav.find(n=>n[0]===page)[2];let html='';const pending=data.tasks.filter(t=>!t.done).sort((a,b)=>a.date.localeCompare(b.date)),minutes=data.logs.reduce((n,l)=>n+l.minutes,0);
if(page==='dashboard'){const days=Math.max(0,Math.ceil((new Date(data.profile.exam+'T00:00:00')-new Date())/86400000));html=head(esc(data.profile.name==='我的'?'每一天，都在靠近目标。':data.profile.name+'，每一天都在靠近目标。'),'这里是你的 IB 学习空间。把大目标，变成今天的一小步。','记录学习','logs')+`<div class="hero"><div><div class="eyebrow">MAKE ROOM FOR PROGRESS</div><h2>属于你的 Diploma 旅程</h2><p>不必一次完成所有事，先完成今天重要的事。</p><button class="primary" data-add="tasks">安排今天的任务 ↗</button></div><div class="hero-art">✳</div></div><div class="stats"><div class="stat"><span class="stat-label">已记录学习</span><strong>${(minutes/60).toFixed(1)} <small>小时</small></strong><small>${data.logs.length} 次认真投入</small></div><div class="stat"><span class="stat-label">待完成任务</span><strong>${pending.length} <small>项</small></strong><small>${pending.filter(t=>t.date<today()).length} 项已逾期</small></div><div class="stat"><span class="stat-label">我的学科</span><strong>${data.subjects.length} <small>/ 6</small></strong><small>${data.subjects.filter(s=>s.level==='HL').length} HL · ${data.subjects.filter(s=>s.level==='SL').length} SL</small></div><div class="stat"><span class="stat-label">距离目标考试</span><strong>${days} <small>天</small></strong><small>目标日期 ${esc(data.profile.exam)}</small></div></div><div class="grid"><section class="panel"><div class="panel-head"><h2>接下来要做的事</h2><a class="text-button" href="#tasks">全部任务 ↗</a></div>${taskRows(pending.slice(0,4))}</section><section class="panel"><div class="panel-head"><h2>本周的积累</h2><span class="tag">最近 7 天</span></div>${weekChart()}<div class="quote">“进步是每一天的积累。”<br>哪怕只是 20 分钟，也是在向前。</div></section></div><div class="section-title"><h2>我的学科 <span class="sub"> / MY SUBJECTS</span></h2><a class="text-button" href="#subjects">管理学科 ↗</a></div><div class="subjects">${subjectCards()||'<div class="panel" style="grid-column:1/-1">'+empty('从你的第一门课开始','选择 HL / SL，建立属于你的六科学习空间。')+'<button data-add="subjects">＋ 添加学科</button></div>'}</div>`}
if(page==='subjects')html=head('我的学科','覆盖六大学科组。按你的实际选课添加课程，点击卡片更新进度与笔记。','添加学科','subjects')+`<div class="panel"><span class="tag">${data.subjects.filter(s=>s.level==='HL').length} HL</span> <span class="tag blue">${data.subjects.filter(s=>s.level==='SL').length} SL</span><p class="sub">通常选择六门课程。课程设置和考核要求请以学校及对应考试届次指南为准。</p></div><div class="subjects">${subjectCards()||empty('你的课程，由你定义','点击右上角添加第一门学科。')}</div>`+groups.map((g,i)=>`<div class="panel" style="margin-bottom:12px"><h3>0${i+1} · ${g[0]}</h3><p class="sub">${g.slice(1).map(esc).join(' · ')}</p></div>`).join('')+`<p class="sub">上方为常见课程示例，添加时支持自定义名称。课程结构参考 <a href="https://www.ibo.org/programmes/diploma-programme/curriculum/" target="_blank" rel="noopener">IB 官方课程目录 ↗</a>。</p>`;
if(page==='tasks')html=head('任务与计划','让作业、复习与重要截止日期，各有着落。','添加任务','tasks')+filters(true)+`<div class="panel" id="list"></div>`;
if(page==='logs')html=head('学习日志','记录知识，也记录你如何理解它。','记录学习','logs')+filters()+`<div class="panel" id="list"></div>`;
if(page==='grades')html=head('成绩追踪','每一次测评，都是调整学习方向的线索。','记录成绩','grades')+`<div class="stats"><div class="stat"><span class="stat-label">测评记录</span><strong>${data.grades.length}</strong></div><div class="stat"><span class="stat-label">平均等级</span><strong>${data.grades.length?(data.grades.reduce((n,g)=>n+g.score,0)/data.grades.length).toFixed(1):'—'}</strong></div><div class="stat"><span class="stat-label">最新记录</span><strong>${data.grades.length?data.grades.slice().sort((a,b)=>b.date.localeCompare(a.date))[0].score:'—'} <small>/ 7</small></strong></div><div class="stat"><span class="stat-label">用途</span><p class="sub">用于个人复盘<br>非官方预估成绩</p></div></div>`+filters()+`<div class="panel" id="list"></div>`;
if(page==='core')html=head('核心项目','研究、思考、行动。把长期项目拆成看得见的进展。','添加记录','core')+`<div class="core-grid">${[['EE','Extended Essay','从研究问题到最终论文，记录每个研究阶段。'],['TOK','Theory of Knowledge','收集知识问题、展览构思与论文反思。'],['CAS','Creativity · Activity · Service','记录经历、行动、反思与学习成果。']].map(([t,n,d])=>{const list=data.core.filter(x=>x.type===t),done=list.filter(x=>x.stage==='已完成').length;return `<section class="panel core-card"><div class="number">${t}</div><h3>${n}</h3><p class="sub">${d}</p><div class="progress"><i style="width:${list.length?done/list.length*100:0}%"></i></div><p class="sub">${done} / ${list.length} 个阶段完成</p></section>`}).join('')}</div><div class="section-title"><h2>项目与阶段 · 包含 IA</h2><span class="tag">${data.core.length} 条记录</span></div><div class="panel">${data.core.length?data.core.map(x=>recordRow(x,'core')).join(''):empty('从一个研究问题开始','添加 IA、EE、TOK 或 CAS 的阶段目标与反思。')}</div>`;
if(page==='focus')html=head('专注时光','留出一段完整的时间，做一件值得的事。')+`<div class="panel timer"><div class="eyebrow">ONE THING AT A TIME</div><div id="timer-display"></div><p class="sub">25 分钟专注 · 结束后可保存为学习日志</p><button class="primary" id="timer-start"></button><button class="outline" id="timer-reset">重置</button><button class="outline" id="timer-save">保存已专注时间</button></div>`;
if(page==='settings')html=head('个人设置','让这个空间更像你自己。')+`<div class="grid"><section class="panel"><h2>我的学习档案</h2><form id="profile-form">${field('你的名字','name','text',data.profile.name,'required maxlength="40"')}${field('目标考试日期','exam','date',data.profile.exam,'required')}<button class="primary" style="margin-top:20px">保存设置</button></form></section><section class="panel"><h2>数据与备份</h2><p class="sub">数据保存在当前设备的浏览器中。清除浏览器数据、切换设备或网址不会自动同步。请定期导出备份。</p><div class="actions" style="justify-content:flex-start"><button class="outline" id="export-settings">导出 JSON</button><button class="outline" id="import">导入备份</button><input type="file" id="import-file" accept="application/json" hidden></div><p class="sub">导入前会确认，导入将替换当前数据。</p><div style="margin-top:35px"><h3>移除学科</h3>${data.subjects.map(s=>`<div class="row"><span class="row-body">${esc(s.name)}</span><button class="delete" data-delete="subjects:${s.id}" aria-label="删除科目">×</button></div>`).join('')||'<p class="sub">暂无学科</p>'}</div></section></div>`;
$('#app').innerHTML=html;bind();if(['tasks','logs','grades'].includes(page))renderList();if(page==='focus')paintTimer()}
function weekChart(){let vals=[];for(let i=6;i>=0;i--){let d=new Date();d.setDate(d.getDate()-i);let key=d.toLocaleDateString('en-CA');vals.push([d.getDate(),data.logs.filter(l=>l.date===key).reduce((n,l)=>n+l.minutes,0)])}let max=Math.max(60,...vals.map(x=>x[1]));return `<div class="week">${vals.map(([d,m])=>`<div class="day" title="${m} 分钟"><div class="bar" style="height:${Math.max(3,m/max*70)}px"></div>${d}日</div>`).join('')}</div>`}
function filters(task=false){return `<div class="filters"><input id="search" placeholder="搜索${task?'任务':'记录'}或科目…" value="${esc(filter)}" aria-label="搜索记录">${task?`<select id="status" aria-label="任务状态"><option value="all">全部任务</option><option value="pending">待完成</option><option value="done">已完成</option></select>`:''}</div>`}
function recordRow(x,kind){return `<div class="row"><div class="row-body"><a href="#" data-edit="${kind}:${x.id}" class="row-title">${esc(x.title)}</a><small>${esc(subjectName(x.subject))} · ${esc(x.date)} ${kind==='logs'?'· '+x.minutes+' 分钟':''}</small>${x.notes?`<div class="note">${esc(x.notes)}</div>`:''}${x.raw?`<small>原始分数 ${esc(x.raw)}</small>`:''}</div><span class="tag ${kind==='grades'?'blue':''}">${kind==='grades'?x.score+' / 7':esc(x.stage||'学习日志')}</span>${kind==='core'?`<span class="tag blue">${esc(x.type)}</span>`:''}<button class="delete" data-delete="${kind}:${x.id}" aria-label="删除记录">×</button></div>`}
function renderList(){let items=data[page].filter(x=>(x.title+' '+subjectName(x.subject)).toLowerCase().includes(filter.toLowerCase()));if(page==='tasks'&&status!=='all')items=items.filter(x=>x.done===(status==='done'));items.sort((a,b)=>page==='tasks'?a.date.localeCompare(b.date):b.date.localeCompare(a.date));$('#list').innerHTML=page==='tasks'?taskRows(items):items.map(x=>recordRow(x,page)).join('')||empty('还没有记录','添加你的第一条记录，从今天开始积累。');bindRows()}
function bindRows(){document.querySelectorAll('[data-edit]').forEach(el=>{el.onclick=e=>{e.preventDefault();let[k,id]=el.dataset.edit.split(':');add(k,id)};if(el.tagName==='ARTICLE')el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();el.click()}}});document.querySelectorAll('[data-delete]').forEach(el=>el.onclick=()=>{let[k,id]=el.dataset.delete.split(':');if(confirm('确定删除这条记录？此操作不可撤销。')){data[k]=data[k].filter(x=>x.id!==id);save();render()}});document.querySelectorAll('[data-check]').forEach(el=>el.onchange=()=>{data.tasks.find(t=>t.id===el.dataset.check).done=el.checked;save();render()})}
function bind(){document.querySelectorAll('[data-add]').forEach(el=>el.onclick=()=>add(el.dataset.add));bindRows();if($('#search'))$('#search').oninput=e=>{filter=e.target.value;renderList()};if($('#status')){$('#status').value=status;$('#status').onchange=e=>{status=e.target.value;renderList()}}if($('#profile-form'))$('#profile-form').onsubmit=e=>{e.preventDefault();data.profile=Object.fromEntries(new FormData(e.target));if(save())toast('档案已更新')};if($('#export-settings'))$('#export-settings').onclick=backup;if($('#import')){$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=importData}if($('#timer-start')){$('#timer-start').onclick=()=>{if(timer.running){timer.remaining=Math.max(0,Math.ceil((timer.end-Date.now())/1000));timer.running=false}else{timer.end=Date.now()+timer.remaining*1000;timer.running=true}paintTimer()};$('#timer-reset').onclick=()=>{timer={remaining:1500,running:false,end:0};paintTimer()};$('#timer-save').onclick=()=>{const remaining=timer.running?Math.max(0,Math.ceil((timer.end-Date.now())/1000)):timer.remaining;const m=Math.floor((1500-remaining)/60);if(m<1)return toast('专注满 1 分钟后即可保存');add('logs');$('#f-title').value='专注学习';$('#f-minutes').value=m;timer={remaining:1500,running:false,end:0};paintTimer()}}}
function backup(){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='ib-atlas-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('备份已导出')}
async function importData(e){try{const file=e.target.files[0];if(!file)return;if(file.size>5e6)throw Error('备份文件超过 5MB');let d=JSON.parse(await file.text());validate(d);if(confirm('导入将替换当前数据。建议先导出备份。继续导入？')){data=d;if(save()){render();toast('备份已恢复')}}}catch(err){toast('导入失败：'+err.message)}}
function validate(d){if(d.version!==1||!d.profile||typeof d.profile.name!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(d.profile.exam))throw Error('档案格式不正确');for(const key of ['subjects','tasks','logs','grades','core']){if(!Array.isArray(d[key])||d[key].length>10000)throw Error('记录格式不正确');for(const x of d[key]){if(!x||(typeof x.id!=='string'||! /^[a-zA-Z0-9_-]{1,100}$/.test(x.id)))throw Error('记录缺少 ID');if(key==='subjects'){if(typeof x.name!=='string'||!['HL','SL'].includes(x.level)||!Number.isInteger(+x.group)||+x.group<0||+x.group>5||!Number.isFinite(x.progress)||x.progress<0||x.progress>100||!Number.isInteger(x.target)||x.target<1||x.target>7)throw Error('科目格式不正确')}else{if(typeof x.title!=='string'||typeof x.date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(x.date))throw Error('记录格式不正确');if(key==='logs'&&(!Number.isFinite(x.minutes)||x.minutes<1||x.minutes>1440))throw Error('时长不正确');if(key==='grades'&&(!Number.isInteger(x.score)||x.score<1||x.score>7))throw Error('成绩不正确')}}}}
let timer={remaining:1500,running:false,end:0};function paintTimer(){if(!$('#timer-display'))return;const s=timer.running?Math.max(0,Math.ceil((timer.end-Date.now())/1000)):timer.remaining;$('#timer-display').textContent=String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');$('#timer-start').textContent=timer.running?'暂停专注':s===0?'已完成':'开始专注';$('#timer-start').disabled=s===0}setInterval(()=>{if(timer.running&&Date.now()>=timer.end){timer.running=false;timer.remaining=0;toast('本次专注已完成！可以保存到学习日志。')}paintTimer()},500);$('#backup').onclick=backup;window.addEventListener('hashchange',()=>{filter='';status='all';render()});render();
